package io.aetheris.orchestrator.trading;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="aetheris_backtest_results") public class BacktestResultEntity {@Id private UUID id;@Column(nullable=false,length=40) private String symbol;private int bars;private int trades;private double trainReturnPct;private double testReturnPct;private double winRatePct;private double maxDrawdownPct;private double finalBalance;@Column(nullable=false) private Instant createdAt;protected BacktestResultEntity(){}public BacktestResultEntity(UUID id,String symbol,int bars,int trades,double trainReturn,double testReturn,double winRate,double drawdown,double finalBalance){this.id=id;this.symbol=symbol;this.bars=bars;this.trades=trades;this.trainReturnPct=trainReturn;this.testReturnPct=testReturn;this.winRatePct=winRate;this.maxDrawdownPct=drawdown;this.finalBalance=finalBalance;this.createdAt=Instant.now();}public UUID getId(){return id;}public String getSymbol(){return symbol;}public int getBars(){return bars;}public int getTrades(){return trades;}public double getTrainReturnPct(){return trainReturnPct;}public double getTestReturnPct(){return testReturnPct;}public double getWinRatePct(){return winRatePct;}public double getMaxDrawdownPct(){return maxDrawdownPct;}public double getFinalBalance(){return finalBalance;}public Instant getCreatedAt(){return createdAt;}}
